var analyzePortfolioHealth = async (items, onChunk) => {
  const promptData = formatHealthCheckData(items);
  const promptText = `\u4EE5\u4E0B\u662F\u6211\u76EE\u524D\u7684\u5EAB\u5B58\u6301\u80A1\uFF0C\u8ACB\u9010\u4E00\u9032\u884C\u5065\u6AA2\u5206\u6790\uFF1A
${promptData}`;
  const payload = {
    prompt: promptText,
    systemInstruction: HEALTH_CHECK_SYSTEM_INSTRUCTION,
    mode: "fast",
    temperature: 0.2,
    thinkingConfig: { thinkingBudget: FLASH_THINKING_BUDGET }
  };
  return onChunk ? callGeminiApiStream(payload, onChunk) : callGeminiApi(payload, "\u7121\u6CD5\u751F\u6210\u5065\u6AA2\u7D50\u679C\u3002");
};
var na = (v, suffix = "") => v == null ? "N/A" : `${v}${suffix}`;
